TEMPLATES: dict[str, dict] = {
    "modern":    {"font": "calibri", "accent": (37, 99, 235),  "header": "left",   "heading": "rule",      "name_size": 24, "body": 10.5},
    "classic":   {"font": "times",   "accent": (17, 17, 17),   "header": "center", "heading": "underline", "name_size": 22, "body": 11},
    "executive": {"font": "georgia", "accent": (30, 58, 95),   "header": "banner", "heading": "caps",      "name_size": 24, "body": 10},
    "creative":  {"font": "segoeui", "accent": (126, 34, 206), "header": "bar",    "heading": "block",     "name_size": 26, "body": 10},
    "minimal":   {"font": "arial",   "accent": (64, 64, 64),   "header": "left",   "heading": "plain",     "name_size": 20, "body": 10},
    "technical": {"font": "verdana", "accent": (4, 120, 87),   "header": "left",   "heading": "leftbar",   "name_size": 20, "body": 9},
    "elegant":   {"font": "cambria", "accent": (127, 29, 29),  "header": "center", "heading": "centered",  "name_size": 24, "body": 10.5},
}

# (regular file, bold file, (regular, bold) ttc collection indexes) for PDF; display name for DOCX.
FONT_FILES = {
    "calibri": ("calibri.ttf", "calibrib.ttf", 0, "Calibri"),
    "times":   ("times.ttf", "timesbd.ttf", 0, "Times New Roman"),
    "georgia": ("georgia.ttf", "georgiab.ttf", 0, "Georgia"),
    "segoeui": ("segoeui.ttf", "segoeuib.ttf", 0, "Segoe UI"),
    "arial":   ("arial.ttf", "arialbd.ttf", 0, "Arial"),
    "verdana": ("verdana.ttf", "verdanab.ttf", 0, "Verdana"),
    "cambria": ("cambria.ttc", "cambriab.ttf", 0, "Cambria"),
    "nirmala": ("Nirmala.ttc", "Nirmala.ttc", (0, 1), "Nirmala UI"),
    "yahei":   ("msyh.ttc", "msyhbd.ttc", 0, "Microsoft YaHei"),
}
# Non-Latin scripts switch to a font that covers them (layout and colours stay the same).
SCRIPT_FONT = {"zh": "yahei", "hi": "nirmala", "ar": "arial"}
TEXT_DARK, TEXT_MUTED = (33, 37, 41), (85, 85, 85)


def _is_title_line(sec_key: str, text: str) -> bool:
    """Short non-bullet lines in experience/education are usually 'Title | Company | Dates'."""
    return sec_key in ("experience", "education", "projects") and len(text.split()) <= 16


# ---------------------------------------------------------------- PDF
class _ResumePDF(FPDF):
    """FPDF subclass that renders a parsed resume with a template style."""

    def __init__(self, tpl: dict, lang: str):
        super().__init__(format="A4")
        self.tpl, self.lang, self.rtl = tpl, lang, lang == "ar"
        self.set_margins(16, 14, 16)
        self.set_auto_page_break(True, 14)
        self._fam = SCRIPT_FONT.get(lang, tpl["font"])
        # "rl-" prefix avoids clashing with FPDF's built-in core font names (times, arial...)
        for fam in {self._fam, "arial", "nirmala", "yahei"}:
            reg, bold, idx, _ = FONT_FILES[fam]
            r_idx, b_idx = idx if isinstance(idx, tuple) else (idx, idx)
            r_path, r_idx = font_file(reg, r_idx)
            b_path, b_idx = font_file(bold, b_idx)
            self.add_font(f"rl-{fam}", "", r_path, collection_font_number=r_idx)
            self.add_font(f"rl-{fam}", "B", b_path, collection_font_number=b_idx)
        self.set_fallback_fonts([f"rl-{f}" for f in ("arial", "nirmala", "yahei") if f != self._fam])
        if lang in ("hi", "ar"):
            self.set_text_shaping(use_shaping_engine=True, direction="rtl" if self.rtl else "ltr")
        self._align = "R" if self.rtl else "L"

    def header(self):
        """Decorative bar for the 'creative' template on every page."""
        if self.tpl["header"] == "bar":
            self.set_fill_color(*self.tpl["accent"])
            self.rect(0 if not self.rtl else self.w - 5, 0, 5, self.h, "F")

    def _font(self, size: float, bold: bool = False, color=TEXT_DARK):
        self.set_font(f"rl-{self._fam}", "B" if bold else "", size)
        self.set_text_color(*color)

    def _write(self, text: str, size: float, bold=False, color=TEXT_DARK, align=None, h=None, indent=0.0):
        self._font(size, bold, color)
        x = self.l_margin + (0 if self.rtl else indent)
        self.set_x(x)
        self.multi_cell(self.epw - indent, h or size * 0.5, text, align=align or self._align,
                        new_x="LMARGIN", new_y="NEXT")

    def render_header(self, doc: dict):
        tpl, style = self.tpl, self.tpl["header"]
        name, headline, contact = doc.get("name", ""), doc.get("headline", ""), doc.get("contact_line", "")
        align = "C" if style == "center" else self._align
        if style == "banner":
            lines = 1 + bool(headline) + bool(contact)
            height = 12 + tpl["name_size"] * 0.42 + 6 * (lines - 1)
            self.set_fill_color(*tpl["accent"])
            self.rect(0, 0, self.w, height, "F")
            self.set_y(8)
            white = (255, 255, 255)
            self._write(name, tpl["name_size"], True, white, h=tpl["name_size"] * 0.45)
            if headline:
                self._write(headline, 11.5, False, (226, 232, 240), h=6)
            if contact:
                self._write(contact, 9, False, (226, 232, 240), h=5)
            self.set_y(height + 4)
            return
        self._write(name, tpl["name_size"], True, tpl["accent"] if style != "center" or tpl["font"] != "times"
                    else TEXT_DARK, align=align, h=tpl["name_size"] * 0.45)
        if headline:
            self._write(headline, 12, False, TEXT_MUTED, align=align, h=6.5)
        if contact:
            self._write(contact, 9, False, TEXT_MUTED, align=align, h=5)
        self.ln(2)

    def render_heading(self, text: str):
        tpl, style = self.tpl, self.tpl["heading"]
        accent = tpl["accent"]
        text = text.upper() if text.isascii() else text
        self.ln(3)
        if self.will_page_break(18):
            self.add_page()
        y = self.get_y()
        if style == "block":
            self.set_fill_color(*accent)
            self.rect(self.l_margin if not self.rtl else self.w - self.r_margin - 3, y + 1, 3, 4.5, "F")
            self._write(text, 12, True, accent, indent=5 if not self.rtl else 0, h=6.5)
        elif style == "leftbar":
            self.set_fill_color(*accent)
            self.rect(self.l_margin if not self.rtl else self.w - self.r_margin - 1.4, y, 1.4, 6, "F")
            self._write(text, 11, True, accent, indent=3.5 if not self.rtl else 0, h=6)
        elif style == "centered":
            self._write(text, 11.5, True, accent, align="C", h=6.5)
            self.set_draw_color(*accent)
            self.set_line_width(0.2)
            mid = self.w / 2
            self.line(mid - 30, self.get_y() + 0.5, mid + 30, self.get_y() + 0.5)
            self.ln(1.5)
        elif style == "plain":
            self._write(text, 12, True, accent, h=6.5)
        else:  # rule / underline / caps
            self._write(text, 11.5 if style != "caps" else 11, True, accent if style != "underline" else TEXT_DARK, h=6.5)
            self.set_draw_color(*(accent if style == "rule" else (150, 150, 150) if style == "caps" else TEXT_DARK))
            self.set_line_width(0.5 if style == "rule" else 0.3)
            self.line(self.l_margin, self.get_y() + 0.3, self.w - self.r_margin, self.get_y() + 0.3)
            self.ln(1.5)
        self.ln(1)

    def render_items(self, sec: dict):
        body = self.tpl["body"]
        for item in sec["items"]:
            if item["type"] == "bullet":
                self._write("•  " + item["text"], body, h=body * 0.52, indent=4)
            elif _is_title_line(sec["key"], item["text"]):
                self.ln(0.8)
                self._write(item["text"], body + 0.5, True, h=body * 0.55)
            else:
                self._write(item["text"], body, h=body * 0.52)
            self.ln(0.6)


def export_pdf(doc: dict, template: str, lang: str) -> bytes:
    """Render the resume structure to PDF bytes."""
    pdf = _ResumePDF(TEMPLATES[template], lang)
    pdf.set_title(doc.get("name") or "Resume")
    pdf.set_author(doc.get("name") or "")
    pdf.set_lang(lang)
    pdf.add_page()
    pdf.render_header(doc)
    for sec in doc["sections"]:
        if sec.get("heading"):
            pdf.render_heading(sec["heading"])
        pdf.render_items(sec)
    return bytes(pdf.output())


# ---------------------------------------------------------------- DOCX
def _hex(rgb) -> str:
    return "%02X%02X%02X" % rgb


def _set_run(run, font: str, size: float, bold=False, color=TEXT_DARK, rtl=False):
    """Apply font (incl. East-Asian/complex-script slots), size, weight and colour to a run."""
    run.font.name, run.font.size, run.font.bold = font, Pt(size), bold
    run.font.color.rgb = RGBColor(*color)
    rpr = run._element.get_or_add_rPr()
    fonts = rpr.find(qn("w:rFonts"))
    if fonts is None:
        fonts = OxmlElement("w:rFonts")
        rpr.insert(0, fonts)
    for attr in ("w:ascii", "w:hAnsi", "w:eastAsia", "w:cs"):
        fonts.set(qn(attr), font)
    if rtl:
        rpr.append(OxmlElement("w:rtl"))


def _p_border(paragraph, side: str, color: str, size: int = 8):
    ppr = paragraph._p.get_or_add_pPr()
    bdr = ppr.find(qn("w:pBdr"))
    if bdr is None:
        bdr = OxmlElement("w:pBdr")
        ppr.append(bdr)
    el = OxmlElement(f"w:{side}")
    for k, v in (("w:val", "single"), ("w:sz", str(size)), ("w:space", "4"), ("w:color", color)):
        el.set(qn(k), v)
    bdr.append(el)


def _p_shading(paragraph, color: str):
    shd = OxmlElement("w:shd")
    for k, v in (("w:val", "clear"), ("w:color", "auto"), ("w:fill", color)):
        shd.set(qn(k), v)
    paragraph._p.get_or_add_pPr().append(shd)


def export_docx(doc: dict, template: str, lang: str) -> bytes:
    """Render the resume structure to DOCX bytes (editable in Word, ATS readable)."""
    tpl = TEMPLATES[template]
    font = FONT_FILES[SCRIPT_FONT.get(lang, tpl["font"])][3]
    rtl = lang == "ar"
    accent = tpl["accent"]
    d = Document()
    for s in d.sections:
        s.left_margin = s.right_margin = Mm(16)
        s.top_margin = s.bottom_margin = Mm(14)
    normal = d.styles["Normal"]
    normal.font.name, normal.font.size = font, Pt(tpl["body"])
    normal.paragraph_format.space_after = Pt(2)
    default_align = WD_ALIGN_PARAGRAPH.RIGHT if rtl else WD_ALIGN_PARAGRAPH.LEFT

    def para(text, size, bold=False, color=TEXT_DARK, align=None, style=None, space_before=0):
        p = d.add_paragraph(style=style)
        p.alignment = align if align is not None else default_align
        p.paragraph_format.space_before = Pt(space_before)
        if rtl:
            p._p.get_or_add_pPr().append(OxmlElement("w:bidi"))
        _set_run(p.add_run(text), font, size, bold, color, rtl)
        return p

    style = tpl["header"]
    center = WD_ALIGN_PARAGRAPH.CENTER if style == "center" else None
    name, headline, contact = doc.get("name", ""), doc.get("headline", ""), doc.get("contact_line", "")
    if style == "banner":
        white, soft = (255, 255, 255), (226, 232, 240)
        for text, size, bold, color in ((name, tpl["name_size"], True, white), (headline, 11.5, False, soft),
                                        (contact, 9, False, soft)):
            if text:
                _p_shading(para(text, size, bold, color), _hex(accent))
    else:
        p = para(name, tpl["name_size"], True, accent if template != "classic" else TEXT_DARK, center)
        if style == "bar":
            _p_border(p, "right" if rtl else "left", _hex(accent), 36)
        if headline:
            para(headline, 12, False, TEXT_MUTED, center)
        if contact:
            para(contact, 9, False, TEXT_MUTED, center)

    for sec in doc["sections"]:
        if sec.get("heading"):
            h = sec["heading"].upper() if sec["heading"].isascii() else sec["heading"]
            hs = tpl["heading"]
            if hs == "block":
                h = "■ " + h
            p = para(h, 11.5, True, TEXT_DARK if hs == "underline" else accent,
                     WD_ALIGN_PARAGRAPH.CENTER if hs == "centered" else None, space_before=10)
            p.paragraph_format.keep_with_next = True
            if hs in ("rule", "underline", "caps", "centered"):
                _p_border(p, "bottom", _hex(accent if hs != "caps" else (150, 150, 150)), 8 if hs == "rule" else 4)
            elif hs == "leftbar":
                _p_border(p, "right" if rtl else "left", _hex(accent), 24)
        for item in sec["items"]:
            if item["type"] == "bullet":
                para(item["text"], tpl["body"], style="List Bullet")
            elif _is_title_line(sec["key"], item["text"]):
                para(item["text"], tpl["body"] + 0.5, True, space_before=4)
            else:
                para(item["text"], tpl["body"])

    d.core_properties.title = name or "Resume"
    d.core_properties.author = name
    buf = io.BytesIO()
    d.save(buf)
    return buf.getvalue()


def export_resume(text: str, template: str, fmt: str, lang: str | None = None) -> bytes:
    """Parse plain resume text and export it as PDF or DOCX."""
    if template not in TEMPLATES:
        raise ValueError("unknown template")
    lang = lang or detect_language(text)
    doc = parse_resume(text)
    if not doc["name"]:
        doc["name"] = "Resume"
    return export_pdf(doc, template, lang) if fmt == "pdf" else export_docx(doc, template, lang)


def safe_filename(name: str, ext: str) -> str:
    """ASCII-only, header-safe download file name."""
    base = re.sub(r"[^A-Za-z0-9]+", "_", name or "").strip("_")[:40] or "resume"
    return f"{base}_resume.{ext}"
